<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use App\Domain\Marketing\MarketingPermission;
use App\Services\Marketing\MarketingPosts;
use Illuminate\Http\Request;
class MarketingPostsController extends Controller {
 private function access(Request $r,bool $edit=false):int{abort_unless(MarketingPermission::allows($r->user(),$edit?MarketingPermission::EDIT:MarketingPermission::VIEW),403);return $r->user()->id;}
 private function boot(Request $r,MarketingPosts $s):array{$id=$this->access($r);$posts=$s->listing($id);$assets=$s->library($id)['assets'];foreach($posts as $p){$keys=array_unique(array_merge(app(\App\Services\Marketing\MarketingPostContent::class)->keys($p),...array_values($p['media_copies']??[])));foreach($keys as $key){$a=$s->asset($id,$key);if($a&&!collect($assets)->contains('id',$a['id']))$assets[]=$a;}}return ['canApproveCost'=>MarketingPermission::allows($r->user(),MarketingPermission::APPROVE_COST),'ai'=>app(\App\Services\Marketing\MarketingPostAi::class)->availability(),'queueEnabled'=>(bool)config('marketing.post_queue_enabled'),'schedulingEnabled'=>(bool)config('marketing.post_queue_enabled')&&(bool)config('marketing.post_scheduling_enabled'),'formats'=>\App\Services\Marketing\MarketingPostFormats::all(),'tiktokPhotoReady'=>\App\Services\Marketing\MarketingPostFormats::photoReady(),'posts'=>$posts,'accounts'=>$s->accounts(),'assets'=>$assets,'videoPublishingEnabled'=>(bool)config('marketing.external_video_publishing_enabled',false)&&$r->user()->is_super_admin,'publishingEnabled'=>(bool)config('marketing.social_publishing_enabled',false)&&$r->user()->is_super_admin,'canEdit'=>MarketingPermission::allows($r->user(),MarketingPermission::EDIT),'csrf'=>csrf_token(),'base'=>url('/admin/marketing/posts/data'),'page'=>$r->routeIs('marketing.preview.calendar')?'calendar':'posts','urls'=>MarketingNavigationController::boot('posts')['urls']];}
 public function index(Request $r,MarketingPosts $s){return response()->view('marketing.posts.index',['boot'=>$this->boot($r,$s)])->header('Cache-Control','private, no-store');}
 public function data(Request $r,MarketingPosts $s){return response()->json($this->boot($r,$s))->header('Cache-Control','private, no-store');}
 public function library(Request $r,MarketingPosts $s){$id=$this->access($r);$d=$r->validate(['q'=>'nullable|string|max:100','page'=>'nullable|integer|min:1|max:10000']);return response()->json($s->library($id,$d['q']??'',(int)($d['page']??1)))->header('Cache-Control','private, no-store');}
 public function write(Request $r,string $action,MarketingPosts $s){$id=$this->access($r,true);$rules=['id'=>'required|uuid','version'=>'required|integer|min:0'];if(!in_array($action,['cancel','refresh','link','delete'],true))$rules+=['title'=>'nullable|string|max:255','copy'=>'nullable|string|max:10000','targets'=>'present|array|max:30','targets.*'=>'required|uuid|distinct','copies'=>'present|array|max:30','copies.*'=>'nullable|string|max:10000','asset'=>'nullable|string|max:100','assets'=>'sometimes|array|max:10','assets.*'=>'string|max:100|distinct','media_copies'=>'sometimes|array|max:30','media_copies.*'=>'array|max:10','media_copies.*.*'=>'string|max:100|distinct','format'=>'sometimes|in:image,carousel,video','ai_context'=>'sometimes|array','ai_context.subject'=>'sometimes|string|max:200','ai_context.facts'=>'sometimes|string|max:5000','ai_context.source'=>'sometimes|in:product,service,topic','ai_context.product_id'=>'nullable|integer','copy_history'=>'sometimes|array|max:20','copy_history.*.copy'=>'sometimes|string|max:10000','copy_history.*.copies'=>'sometimes|array|max:30','type'=>'required|in:Post,Reel','tz'=>'required|timezone','due'=>'nullable|date','options'=>'nullable|array|max:30','options.*'=>'array'];$d=$r->validate($rules);if($action==='delete')return response()->json(['post'=>$s->delete($id,$d)])->header('Cache-Control','no-store');if($action==='link')return response()->json(['post'=>app(\App\Services\Marketing\MarketingImagePublisher::class)->findLinks($id,$d['id'])])->header('Cache-Control','private, no-store');if(config('marketing.post_queue_enabled')&&in_array($action,['publish','schedule'],true)){abort_unless($r->user()->is_super_admin,403);return response()->json(['post'=>app(\App\Services\Marketing\MarketingPostQueue::class)->submit($id,$d,$action==='publish')])->header('Cache-Control','no-store');}if(config('marketing.post_queue_enabled')&&$action==='refresh'){return response()->json(['post'=>app(\App\Services\Marketing\MarketingPostQueue::class)->requestRefresh($id,$d['id'])])->header('Cache-Control','no-store');}if(in_array($action,['publish','refresh'],true)){abort_unless($r->user()->is_super_admin,403);$video=$action==='publish'?($s->asset($id,$d['asset']??'')['kind']??'')==='video':str_starts_with((string)(\App\Models\MarketingPost::where('user_id',$id)->find($d['id'])?->document['asset']??''),'upload:')||str_starts_with((string)(\App\Models\MarketingPost::where('user_id',$id)->find($d['id'])?->document['asset']??''),'video:');$multi=$action==='publish'?\App\Services\Marketing\MarketingMultiImagePublisher::applies($d):\App\Services\Marketing\MarketingMultiImagePublisher::applies(\App\Models\MarketingPost::where('user_id',$id)->findOrFail($d['id'])->document);$publisher=app($multi?\App\Services\Marketing\MarketingMultiImagePublisher::class:($video?\App\Services\Marketing\MarketingVideoPublisher::class:\App\Services\Marketing\MarketingImagePublisher::class));$post=$action==='publish'?$publisher->start($id,$d):$publisher->refresh($id,$d['id']);}else $post=$s->write($id,$action,$d);return response()->json(['post'=>$post])->header('Cache-Control','private, no-store');}
 public function contextProducts(Request $r){$this->access($r,true);$d=$r->validate(['q'=>'nullable|string|max:100']);return response()->json(['products'=>\App\Models\Product::where('title','like','%'.($d['q']??'').'%')->orderBy('title')->limit(20)->get(['id','title'])])->header('Cache-Control','private, no-store');}
 public function ai(Request $r,string $action){$user=$this->access($r,true);$service=app(\App\Services\Marketing\MarketingPostAi::class);if($action==='generate'){abort_unless(MarketingPermission::allows($r->user(),MarketingPermission::APPROVE_COST),403,'Cost approval permission is required.');$d=$r->validate(['id'=>'required|uuid','approved'=>'required|accepted']);return response()->json($service->generate($user,$d['id']))->header('Cache-Control','private, no-store');}$d=$r->validate(['copy'=>'present|nullable|string|max:10000','targets'=>'present|array|max:10','targets.*'=>'uuid|distinct','action'=>'required|in:draft,shorten,cta,tone','context'=>'required|array','context.source'=>'required|in:product,service,topic','context.product_id'=>'nullable|integer','context.subject'=>'required|string|max:200','context.facts'=>'present|string|max:5000','context.language'=>'required|in:English,Chinese,Malay','context.tone'=>'required|in:Friendly,Concise,Professional','context.purpose'=>'required|string|max:100','context.audience'=>'required|string|max:200']);return response()->json($service->quote($user,array_replace($d,['copy'=>$d['copy']??''])))->header('Cache-Control','private, no-store');}
 public function upload(Request $r,MarketingPosts $s){$id=$this->access($r,true);$r->validate(['file'=>'required|file|max:65536']);$asset=app(\App\Services\Marketing\MarketingPostMedia::class)->store($id,$r->file('file'));return response()->json(['asset'=>$s->asset($id,$asset)])->header('Cache-Control','private, no-store');}
 public function creator(Request $r,string $connection){$this->access($r,true);abort_unless($r->user()->is_super_admin,403);return response()->json(['creator'=>app(\App\Services\Marketing\MarketingVideoPublisher::class)->creator($connection)])->header('Cache-Control','private, no-store');}
 public function delivery(Request $r,int $attempt){if($r->has('index')){abort_unless(ctype_digit((string)$r->query('index'))&&(int)$r->query('index')<10,404);return app(\App\Services\Marketing\MarketingMultiImagePublisher::class)->delivery($attempt,(int)$r->query('index'));}return app(\App\Services\Marketing\MarketingImagePublisher::class)->delivery($attempt);}
 public function media(Request $r,string $asset,MarketingPosts $s){$id=$this->access($r);abort_unless($s->asset($id,$asset),404);if(str_starts_with($asset,'image:')){$row=\App\Models\ProductImage::findOrFail(substr($asset,6));return response()->file($s->imagePath($row->path),['Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}if(str_starts_with($asset,'upload:'))return response()->file($s->videoFile($id,$asset),['Content-Type'=>($s->asset($id,$asset)['kind']==='image'?'image/jpeg':'video/mp4'),'Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);[$kind,$run,$format]=explode(':',$asset);$row=\App\Models\MarketingTemplateRun::findOrFail($run)->result['formats'][$format];return response()->file(app(\App\Services\Marketing\MarketingVideoFiles::class)->file($row['path'],$row['sha256']),['Content-Type'=>'video/mp4','Cache-Control'=>'private, no-store','X-Content-Type-Options'=>'nosniff']);}
}
